clearScene();setBig(null);setEq(null);
var X0=340,XW=660,VMAX=2.4,YB=330,PK=150;
function vx(v){return X0+v/VMAX*XW;}
function bell(sd,cls){var p=[],sp=sd/VMAX*XW;
  for(var i=0;i<=80;i++){var x=X0+XW*i/80,u=(x-vx(0.9))/sp;
    p.push([x,YB-PK*Math.exp(-0.5*u*u)]);}
  curve(p,"fit "+cls);}
E.gS.append("path").attr("class","axline").attr("d","M"+X0+","+YB+"L"+(X0+XW)+","+YB+"");
E.gS.append("path").attr("class","axline y").attr("d","M"+vx(0.9)+",160L"+vx(0.9)+","+(YB+10));
note("真值 0.9",vx(0.9),150,"y");
bell(0.5102,"r");
note("σ = 0.5102",vx(1.72),236,"r");
note("标准差，真值 0.9",640,390,"y");
setCap("估计量是无偏的。但<b>标准差 0.51，而被估的量只有 0.9</b>。");

